CREATE TABLE IF NOT EXISTS segments(id INTEGER PRIMARY KEY, work TEXT NOT NULL, sec TEXT NOT NULL, idx INTEGER NOT NULL, he TEXT NOT NULL, plain TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS seg_loc ON segments(work,sec,idx);
CREATE TABLE IF NOT EXISTS comments(id INTEGER PRIMARY KEY, work TEXT NOT NULL, sec TEXT NOT NULL, idx INTEGER NOT NULL, who TEXT NOT NULL, n INTEGER NOT NULL, he TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS com_loc ON comments(work,sec);
CREATE TABLE IF NOT EXISTS xrefs(id INTEGER PRIMARY KEY, work TEXT NOT NULL, sec TEXT NOT NULL, idx INTEGER NOT NULL, cat TEXT NOT NULL, items TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS xr_loc ON xrefs(work,sec);

CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, level TEXT NOT NULL DEFAULT 'student', salt TEXT NOT NULL, hash TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS groups(id INTEGER PRIMARY KEY, name TEXT NOT NULL, code TEXT NOT NULL UNIQUE, owner INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(group_id INTEGER NOT NULL, user_id INTEGER NOT NULL, PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS notes(
  id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, work TEXT NOT NULL, sec TEXT NOT NULL, idx INTEGER NOT NULL,
  ws INTEGER, we INTEGER, quote TEXT, kind TEXT NOT NULL, parent_id INTEGER, title TEXT, body TEXT NOT NULL,
  visibility TEXT NOT NULL DEFAULT 'public', group_id INTEGER, tags TEXT NOT NULL DEFAULT '', level TEXT NOT NULL,
  score INTEGER NOT NULL DEFAULT 0, accepted INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS notes_loc ON notes(work,sec,idx);
CREATE INDEX IF NOT EXISTS notes_parent ON notes(parent_id);
CREATE TABLE IF NOT EXISTS note_links(note_id INTEGER NOT NULL, work TEXT NOT NULL, sec TEXT NOT NULL, idx INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS nl_note ON note_links(note_id);
CREATE INDEX IF NOT EXISTS nl_loc ON note_links(work,sec);
CREATE TABLE IF NOT EXISTS votes(note_id INTEGER NOT NULL, user_id INTEGER NOT NULL, v INTEGER NOT NULL, PRIMARY KEY(note_id,user_id));
CREATE TABLE IF NOT EXISTS dupflags(note_id INTEGER NOT NULL, user_id INTEGER NOT NULL, of_id INTEGER NOT NULL, PRIMARY KEY(note_id,user_id));
CREATE TABLE IF NOT EXISTS chavrusa(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, topic TEXT NOT NULL, ref_label TEXT, when_text TEXT NOT NULL, tz TEXT, lang TEXT, level_wanted TEXT, details TEXT, link TEXT, status TEXT NOT NULL DEFAULT 'open', created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS responses(id INTEGER PRIMARY KEY, chav_id INTEGER NOT NULL, user_id INTEGER NOT NULL, message TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS resp_chav ON responses(chav_id);
CREATE TABLE IF NOT EXISTS align(work TEXT NOT NULL, sec TEXT NOT NULL, idx INTEGER NOT NULL, pairs TEXT NOT NULL, PRIMARY KEY(work,sec,idx)) WITHOUT ROWID;
